        collection thread.  This parameter is only valid if ``default_timeout``
        is > 0 (``ValueError`` is raised otherwise).
    '''
    def __init__(
        self, hashing=True, key_join='|', debug=False, prefix=None,
        quiet=False, default_timeout=0, gc_thread_wait=None
    ):
        self._prefix = prefix or ''
        self._hashing = hashing
        self._key_join = key_join
        self._debug = debug
        self._quiet = quiet
        self._cache = True  # Allow for ``nocache``
        self._data_store = {}
        self._default_timeout = default_timeout
        self._gc_thread_wait = gc_thread_wait
        self._gc_thread = None
        self._do_gc_thread = False
        self._gc_lock = Lock()
        self.counters = {}  # Only enabled with ``debug``

        # Force all calls to use this value instead of default, or what was
        # used during decorator creation.
        self._override_timeout = None

        if default_timeout and not isinstance(default_timeout, int):
            raise ValueError("Default timeout can only be `int`")

        if self._gc_thread_wait and not default_timeout:
            raise ValueError("gc_thread_wait requires default_timeout > 0")

        if self._gc_thread_wait:
            self._do_gc_thread = True
            self._gc_thread = Thread(target=self._gc)
            self._gc_thread.daemon = True
            self._gc_thread.start()

    @property
    def data_store(self):
        '''Underlying mapping of cache keys to :class:`CachedItem` values.'''
        return self._data_store

    # Default stuff to override MutableMapping ABC ############################
    def __len__(self):
        return len([x for x, y in self.items() if not self._is_init_value(y)])

    def __getitem__(self, key):
        '''Only return the item if it's not the INIT value'''
        with self._gc_lock:
            if (key not in self._data_store) or self._is_init_value(self._data_store[key]):
                raise KeyError(key)
            return self._data_store[key]

    def __setitem__(self, key, value):
        with self._gc_lock:
            self._data_store[key] = value

    def __delitem__(self, key):
        with self._gc_lock:
            del self._data_store[key]

    def __iter__(self):
        '''
        Override ``iter()``.  This can make things slow, but it's the only
        way to prevent the underlying object from changing during iteration.
        '''
        with self._gc_lock:
            # Copy first so we don't hold the lock across yields (and so a
            # dict view can't change under the caller).
            keys = list(self._data_store.keys())
        for x in keys:
            yield x

    # Override some of the *normal* methods to include the lock ###############
    def clear(self):
        '''Clear the cache'''
        with self._gc_lock:
            self._data_store.clear()
            self.counters.clear()

    def keys(self):
        '''Return a list of keys in the cache'''
        with self._gc_lock:
            return list(self._data_store.keys())

    def items(self):
        '''Return all items in the cache as a list of ``tuple(key, value)``'''
        with self._gc_lock:
            return list(self._data_store.items())

    def values(self):
        '''Return a list of cached values'''
        with self._gc_lock:
            return list(self._data_store.values())

    def pop(self, key):
        '''Remove the cached value specified by ``key``'''
        with self._gc_lock:
            return self._data_store.pop(key)

    def popitem(self):
        '''Remove a random item from the cache (only useful during testing)'''
        with self._gc_lock:
            return self._data_store.popitem()
    ###########################################################################

    def _is_init_value(self, value):
        '''True for the placeholder stored before an explicit key is filled.'''
        if value is INIT_CACHE_VALUE:
            return True
        try:
            return (
                isinstance(value, tuple) and
                len(value) == 3 and
                value[0] == INIT_CACHE_VALUE.value and
                value[1] is None and
                value[2] is None
            )
        except Exception:
            return False

    def _is_key_initialized(self, key):
        with self._gc_lock:
            return self._is_init_value(self._data_store.get(key))

    def _get_cached_item(self, key):
        '''Return a stored item, or ``None`` if missing / not yet filled.'''
        with self._gc_lock:
            item = self._data_store.get(key, None)
        if item is None or self._is_init_value(item):
            return None
        return item

    def _from_timestamp(self, timestamp):
        '''Convert a timestamp string (or epoch number) to an epoch value'''
        if isinstance(timestamp, bool):
            raise ValueError("Invalid timestamp")
        if isinstance(timestamp, (int, float)):
            return float(timestamp)
        # Legacy values were produced by ``time.asctime()`` (English, C locale).
        # Parse with an explicit format so a non-English locale can't break it.
        try:
            return time.mktime(time.strptime(timestamp, '%a %b %d %H:%M:%S %Y'))
        except Exception:
            return time.mktime(time.strptime(timestamp))

    def _to_timestamp(self, epoch=None):
        '''Convert an epoch value to a timestamp string'''
        if epoch:
            return time.asctime(time.localtime(epoch))

        return time.asctime()

    def _coerce_epoch(self, value):
        '''
        Normalize a timeout / time_added value to an epoch float.

        ``None``, ``0`` and other falsy values mean "no timestamp".
        Numeric values are epochs.  Strings are legacy ``asctime`` values.
        '''
        if not value:
            return None
        if isinstance(value, bool):
            return None
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, _STRING_TYPES):
            try:
                return float(self._from_timestamp(value))
            except Exception:
                return None
        return None

    def _is_expired(self, item, now=None):
        '''Return True if ``item`` has a timeout that is already in the past.'''
        epoch = self._coerce_epoch(getattr(item, 'timeout', None))
        if epoch is None:
            return False
        if now is None:
            now = time.time()
        return now > epoch

    def _debug_print(self, *args):
        if self._debug and not self._quiet:
            print(*args)

    def dump(self):
        '''Dump the entire cache as a JSON string'''
        with self._gc_lock:
            snapshot = self._data_store.copy()
        return json.dumps(snapshot, indent=4, separators=(',', ': '))

    def _apply_prefix(self, key):
        '''Prefix every cache key with the configured prefix (if any).'''
        if not self._prefix:
            return key
        return '{prefix}{join}{key}'.format(
            prefix=self._prefix, join=self._key_join, key=key)

    def _to_bytes(self, text):
        if isinstance(text, bytes):
            return text
        return text.encode('utf-8')

    def _safe_repr(self, value, seen=None):
        '''Order-stable, exception-safe repr used to build cache keys.'''
        if seen is None:
            seen = set()
        try:
            vid = id(value)
        except Exception:
            vid = None
        if vid is not None and vid in seen:
            return '<recursion>'

        if value is None or isinstance(value, _PRIMITIVE_TYPES):
            try:
                return repr(value)
            except Exception:
                return '<unrepr>'

        if isinstance(value, dict):
            if vid is not None:
                seen.add(vid)
            try:
                parts = []
                for k in sorted(list(value.keys()), key=lambda item: self._safe_repr(item, seen)):
                    parts.append('%s: %s' % (
                        self._safe_repr(k, seen),
                        self._safe_repr(value[k], seen),
                    ))
                return '{%s}' % ', '.join(parts)
            finally:
                if vid is not None:
                    seen.discard(vid)

        if isinstance(value, (list, tuple)):
            if vid is not None:
                seen.add(vid)
            try:
                inner = ', '.join(self._safe_repr(v, seen) for v in value)
                if isinstance(value, list):
                    return '[%s]' % inner
                if len(value) == 1:
                    return '(%s,)' % inner
                return '(%s)' % inner
            finally:
                if vid is not None:
                    seen.discard(vid)

        if isinstance(value, (set, frozenset)):
            if vid is not None:
                seen.add(vid)
            try:
                parts = sorted(self._safe_repr(v, seen) for v in value)
                return '{%s}' % ', '.join(parts)
            finally:
                if vid is not None:
                    seen.discard(vid)

        try:
            return repr(value)
        except Exception:
            return '<%s id=%s>' % (type(value).__name__, id(value))

    def _param_names(self, func):
        if hasattr(inspect, 'signature'):
            try:
                return [p.name for p in inspect.signature(func).parameters.values()]
            except (TypeError, ValueError):
                pass
        getter = getattr(inspect, 'getfullargspec', None) or getattr(inspect, 'getargspec', None)
        if getter is None:
            return []
        spec = getter(func)
        names = list(spec.args)
        varargs = getattr(spec, 'varargs', None)
        if varargs:
            names.append(varargs)
        for kw in getattr(spec, 'kwonlyargs', None) or []:
            names.append(kw)
        varkw = getattr(spec, 'varkw', None) or getattr(spec, 'keywords', None)
        if varkw:
            names.append(varkw)
        return names

    def _bind_args(self, func, args, kwargs):
        '''
        Bind ``args``/``kwargs`` to ``func``'s signature, including defaults.

        ``inspect.getargspec`` cannot handle annotations or keyword-only
        parameters (and is gone on modern Python), which previously aborted
        the call before anything was stored.
        '''
        if hasattr(inspect, 'signature'):
            sig = inspect.signature(func)
            bound = sig.bind(*args, **kwargs)
            arguments = dict(bound.arguments)
            if hasattr(bound, 'apply_defaults'):
                bound.apply_defaults()
                arguments = dict(bound.arguments)
            else:
                for param in sig.parameters.values():
                    if (param.name not in arguments and
                            param.default is not inspect.Parameter.empty):
                        arguments[param.name] = param.default
            return arguments
        return inspect.getcallargs(func, *args, **kwargs)

    def _calculate_key(self, func, args, kwargs, cached_key=None):
        '''
        Calculates the cache key based on the function, inputs, and object
        settings.

        :param code func: The function being cached
        :param tuple args: Any ``*args`` used to call the function
        :param dict kwargs: Any ``*kwargs`` used to call the function
        :param str cached_key: The `keyed_cache`, if any
        '''
        if cached_key:
            # Explicit keys are stored under the configured prefix so the
            # entry can be found alongside auto-generated keys.  Hit counters
            # still use the raw key (see ``cached``).
            return self._apply_prefix(cached_key)

        try:
            bound = dict(self._bind_args(func, args, kwargs))
        except TypeError:
            raise
        except Exception:
            bound = {}
            names = self._param_names(func)
            for name, value in zip(names, args):
                bound[name] = value
            bound.update(kwargs)

        # Methods: identify the instance/class stably.  Using ``repr(self)``
        # either throws (cache write never happens) or changes whenever the
        # instance changes, so the same call never hits and counters stay
        # empty.  ``id()`` keeps one entry per distinct object + arguments.
        param_names = self._param_names(func)
        if param_names and param_names[0] in ('self', 'cls') and param_names[0] in bound:
            bound[param_names[0]] = ('id', id(bound[param_names[0]]))

        parts = []
        for name in sorted(list(bound.keys()), key=str):
            parts.append((name, self._safe_repr(bound[name])))
        serialized = repr(parts)

        if self._hashing:
            formatted_key = sha224(self._to_bytes(serialized)).hexdigest()
        else:
            formatted_key = serialized

        base = '{name}{join}{formatted_key}'.format(
            name=getattr(func, '__name__', 'func'),
            join=self._key_join,
            formatted_key=formatted_key,
        )
        return self._apply_prefix(base)

    def _update_counter(self, key):
        '''Keeps track of cache hits'''
        if not self._debug:
            return

        with self._gc_lock:
            if key in self.counters:
                self.counters[key] += 1
            else:
                self.counters[key] = 1

    def _gc(self):
        '''
        This is the garbage collection thread that periodically calls our
        collect method.
        '''
        tnext = time.time() + self._gc_thread_wait
        while self._do_gc_thread:
            if time.time() > tnext:
                self.collect()
                tnext = time.time() + self._gc_thread_wait

            time.sleep(1)

    def collect(self, since=None):
        '''
        Clear any item from the cache that has timed out.
        '''
        remove_keys = []
        now = time.time()
        for key, item in self.items():
            if self._is_init_value(item):
                continue
            expired = False
            try:
                expired = self._is_expired(item, now=now)
            except Exception:
                expired = False

            newer_than_since = False
            if since is not None:
                added = self._coerce_epoch(getattr(item, 'time_added', None))
                if added is not None and added > since:
                    newer_than_since = True

            if expired or newer_than_since:
                self._debug_print('collecting : %s' % key)
                remove_keys.append(key)

        for key in remove_keys:
            try:
                del self[key]
            except KeyError:
                pass

    # Decorators ##############################################################
    def clear_cache(self):
        '''
        A decorator used to clear the cache everytime the function is called.

        For example, let's say you have a "discovery" function that stores
        data read by other functions, and those function use caching.  You want
        to use ``@c.clear_cache()`` for your main function so you don't have
        to worry about cache being stale.
        '''
        def real_decorator(function):
            @wraps(function)
            def wrapper(*args, **kwargs):
                self.clear()
                return function(*args, **kwargs)
            return wrapper
        return real_decorator

    def cached(self, key=None, timeout=None):
        '''
        A decorator used to memoize the return of a function call.

        Can be used as ``@cache.cached`` or ``@cache.cached()``.
        '''
        if timeout and not isinstance(timeout, int):
            raise ValueError("timeout can only be `int`")

        # ``@cache.cached`` without parentheses passes the function as the
        # first argument.  Treating that as a cache key stored the function
        # object and returned the decorator factory, so calls never wrote
        # real entries (especially visible after ``clear()`` dropped the
        # init sentinel).
        func = None
        if callable(key):
            func = key
            key = None

        if key:
            full_key = self._apply_prefix(key)
            # `key in self` will return False if the key either doesn't exist,
            # or it's set to the INIT value.  Therefore, we need to call
            # `_is_key_initialized()` to check that condition.
            if (full_key in self) or self._is_key_initialized(full_key):
                raise ValueError("cache key '%s' already exists" % key)
            # Set the default value so we can check for collisions when the
            # next decorator is called.
            self[full_key] = INIT_CACHE_VALUE

        def real_decorator(function, timeout=timeout):
            if timeout is None:
                effective_timeout = self._default_timeout
            else:
                effective_timeout = timeout
            try:
                function.__cached_timeout__ = effective_timeout
            except Exception:
                pass

            @wraps(function)
            def wrapper(*args, **kwargs):
                # Check the timeout here, since this is the call and not the
                # instantiation.
                if not self._cache:
                    return function(*args, **kwargs)

                cache_key = self._calculate_key(
                    function, args, kwargs, cached_key=key)
                # Storage keys include ``Cache.prefix``.  An explicit decorator
                # key is what callers look up in ``counters``.
                counter_key = key if key else cache_key

                # Let `override_timeout` do its thing
                if self._override_timeout is not None:
                    call_timeout = self._override_timeout
                else:
                    call_timeout = getattr(
                        function, '__cached_timeout__', effective_timeout)

                item = self._get_cached_item(cache_key)
                if item is not None and not self._is_expired(item):
                    self._debug_print('cache hit : %s' % cache_key)
                    self._update_counter(counter_key)
                    return item.value

                if item is not None:
                    self._debug_print('cache timeout: %s' % cache_key)
                else:
                    self._debug_print('caching %s' % cache_key)

                value = function(*args, **kwargs)
                now = time.time()
                # Store an absolute epoch (or ``None`` when there is no
                # timeout).  A falsy timeout must NOT be written as ``0``,
                # which is far in the past and would expire immediately.
                expires = (now + call_timeout) if call_timeout else None
                result = CachedItem(
                    value=value,
                    timeout=expires,
                    time_added=now)
                self[cache_key] = result
                return value

            return wrapper

        if func is not None:
            return real_decorator(func)
        return real_decorator

    def serialize(self, filename):
        '''
        Serialize the cache to a filename.  This process uses ``pickle``; Do
        not use this function if you are caching something that is not
        picklable!
        '''
        with self._gc_lock:
            snapshot = dict(self._data_store)
        with open(filename, 'wb') as fh:
            pickle.dump(snapshot, fh, -1)

    def deserialize(self, filename):
        '''
        Read the serialized cache data from a file.
        '''
        with open(filename, 'rb') as fh:
            data = pickle.load(fh)
        with self._gc_lock:
            self._data_store = data

#!/usr/bin/env python
# coding: utf-8
'''
yamicache : Yet another in-memory cache module ('yami' sounds better to me than
'yaim')

This module provides a simple in-memory interface for caching results from
function calls.
'''

# Imports #####################################################################
from __future__ import print_function
import json
import time
import inspect
import contextlib
import collections
from hashlib import sha224
from functools import wraps
from threading import Lock, Thread
try:
    from collections.abc import MutableMapping
except ImportError:  # pragma: no cover
    from collections import MutableMapping
try:
    import cPickle as pickle
except ImportError:
    import pickle
try:
    _STRING_TYPES = (basestring,)
    _PRIMITIVE_TYPES = (bool, int, long, float, complex, str, unicode, bytes)
except NameError:
    _STRING_TYPES = (str,)
    _PRIMITIVE_TYPES = (bool, int, float, complex, str, bytes)


# Globals #####################################################################
__all__ = ['Cache', 'nocache', 'override_timeout']


@contextlib.contextmanager
def override_timeout(cache_obj, timeout):
    previous = cache_obj._override_timeout
    cache_obj._override_timeout = timeout

    try:
        yield
    finally:
        # Restoring the previous value re-disables the override when it was
        # unset (``None``) and supports nested overrides.
        cache_obj._override_timeout = previous


@contextlib.contextmanager
def nocache(cache_obj):
    '''
    Use this context manager to temporarily disable all caching for an
    object.

    Example:

        >>> from yamicache import Cache, nocache
        >>> c = Cache()
        >>> @c.cached
        ... def test():
        ...     return 4
        ...
        >>> with nocache(c):
        ...     test()
        ...
        4
        >>> print c.data_store
        {}
        >>>

    '''
    previous = cache_obj._cache
    cache_obj._cache = False

    try:
        yield
    finally:
        # Re-enable caching.  ``previous`` is normally ``True``; restoring it
        # (rather than writing a public ``cache`` attribute) is what makes
        # later calls actually get stored again.
        cache_obj._cache = previous


CachedItem = collections.namedtuple('CachedItem', 'value timeout time_added')
INIT_CACHE_VALUE = CachedItem("<value not cached yet>", None, None)


class Cache(MutableMapping):
